<?php
require __DIR__.'/../app/bootstrap.php';$u=require_seller();require_commerce();$order=order_record((int)param('id'),$u);if((int)$order['seller_id']!==(int)$u['id'])fail(404,t('Order not found.'));$err=[];
$transitions=['placed'=>['confirmed','cancelled'],'confirmed'=>['preparing','cancelled'],'preparing'=>['ready'],'ready'=>['completed'],'completed'=>[],'cancelled'=>[]];
if(post()){$next=val('status');if(!in_array($next,$transitions[$order['status']]??[],true))$err[]=t('That status change is not available.');else{db()->beginTransaction();$n=q('UPDATE orders SET status=?,updated_at=? WHERE id=? AND seller_id=? AND status=?',[$next,now(),$order['id'],$u['id'],$order['status']])->rowCount();if($n!==1){db()->rollBack();$err[]=t('This order changed in another session. Reload before trying again.');}else{record_order_event($order,$next,(int)$u['id']);db()->commit();flash(t('Order status updated.'));go('seller/order.php?id='.$order['id']);}}}
$items=all('SELECT * FROM order_items WHERE order_id=? ORDER BY id',[$order['id']]);$title=t('Order ').$order['reference'];require ROOT.'/app/workspace-start.php'; ?>
<div class="dash-header"><h1><?=e(t('Order'))?> <?=e($order['reference'])?></h1><a class="pill" href="<?=e(url('seller/orders.php'))?>"><?=e(t('← Orders'))?></a></div><?php errors($err); ?><div class="two-columns"><section class="panel padded"><?php render_order_summary($order,$items); ?><a class="pill compact space-top" href="<?=e(url('track-order.php?reference='.rawurlencode($order['reference'])))?>"><?=e(t('Track order'))?></a></section><section class="panel padded"><h2><?=e(t('Customer details'))?></h2><p><strong><?=e($order['customer_name'])?></strong><br><?=e($order['customer_phone'])?></p><?php if($order['note']): ?><p><strong><?=e(t('Note:'))?></strong> <?=nl2br(e($order['note']))?></p><?php endif ?><h2><?=e(t('Update progress'))?></h2><p class="hint"><?=e(t('Current status:'))?> <?=e(status_label($order))?></p><div class="order-status-actions"><?php foreach($transitions[$order['status']]??[] as $next): $preview=$order;$preview['status']=$next; ?><form method="post" <?=$next==='cancelled'?'data-confirm="Cancel this order?"':''?>><?=csrf()?><input type="hidden" name="status" value="<?=e($next)?>"><button class="pill <?=$next==='cancelled'?'danger':'primary'?>"><?=$next==='completed'?($order['fulfillment']==='pickup'?t('Mark as Collected'):t('Mark as Delivered')):e(status_label($preview))?></button></form><?php endforeach ?><?php if(!$transitions[$order['status']]): ?><p><?=e(t('This order is closed.'))?></p><?php endif ?></div></section></div><?php if(experience_ready()): $foodFeedback=all('SELECT DISTINCT r.* FROM product_reviews r JOIN order_items i ON i.product_key=r.product_key WHERE i.order_id=? AND r.user_id=? AND r.seller_id=? ORDER BY r.updated_at DESC',[$order['id'],$order['customer_id'],$u['id']]);if($foodFeedback): ?><section class="panel padded space-top"><h2><?=e(t('Customer food reviews'))?></h2><?php foreach($foodFeedback as $feedback): ?><article class="review-card"><h3><?=e($feedback['product_name'])?></h3><?=rating_html((float)$feedback['rating'],1)?><p><?=nl2br(e($feedback['review_text']))?></p></article><?php endforeach ?></section><?php endif;endif ?><?php if(experience_ready()): ?><div data-track-panel data-track-url="<?=e(url('track-order.php?format=json&reference='.rawurlencode($order['reference'])))?>"><?=tracking_html($order)?></div><?php order_map($order);if($order['status']==='completed' && (int)$order['customer_id']!==(int)$u['id']): ?><section class="panel padded space-top"><h2><?=e(t('Order feedback'))?></h2><a class="pill primary" href="<?=e(url('seller/review-customer.php?id='.$order['id']))?>"><?=e(t('Review customer'))?></a></section><?php elseif($order['fulfillment']==='delivery' && !in_array($order['status'],['completed','cancelled'],true)): ?><section class="panel padded space-top"><h2><?=e(t('Rider location'))?></h2><p><?=e(t('Create a temporary link for your delivery rider to view the destination and share a location pin.'))?></p><a class="pill" href="<?=e(url('seller/delivery-link.php?id='.$order['id']))?>"><?=e(t('Manage rider link'))?></a></section><?php endif;endif;require ROOT.'/app/workspace-end.php'; ?>
